"""Build original four-language lesson-3 content; preserve all archived lesson data."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def T(ru,uk,en,sv):return dict(ru=ru,uk=uk,en=en,sv=sv)
def S(s):return T(s,s,s,s)
def E(s,ru,uk,en):return dict(sv=s,meaning=T(ru,uk,en,s))
def line(s,ru,uk,en,speaker=None,annotations=None):
 d=dict(sv=s,ru=ru,uk=uk,en=en)
 if speaker:d['speaker']=speaker
 if annotations:d['annotations']=annotations
 return d
C=dict(version=1,id='pronouns-chapter-v1',description=T('Кто действует, кого видят и кому принадлежит вещь: учимся выбирать шведские местоимения по смыслу и роли в предложении.','Хто діє, кого бачать і кому належить річ: вчимося обирати шведські займенники за змістом і роллю в реченні.','Who acts, who is seen and who owns something: choose Swedish pronouns by meaning and sentence role.','Vem handlar, vem blir sedd och vem äger något? Välj svenska pronomen efter betydelse och satsdel.'),goals=[T('Различать подлежащее и дополнение.','Розрізняти підмет і додаток.','Distinguish subject and object.','Skilja subjekt från objekt.'),T('Согласовывать принадлежность с en, ett и множественным числом.','Узгоджувати належність з en, ett і множиною.','Match possessives to en, ett and plural nouns.','Anpassa possessiva former till en, ett och plural.'),T('Выбирать den/det/de и понимать разговорное dom.','Обирати den/det/de й розуміти розмовне dom.','Choose den/det/de and understand spoken dom.','Välja den/det/de och förstå talat dom.'),T('Объяснять, чья вещь: sin или hans/hennes/deras.','Пояснювати, чия річ: sin чи hans/hennes/deras.','Explain ownership with sin or hans/hennes/deras.','Förklara ägande med sin eller hans/hennes/deras.')],sections=[],tables=[],dialogues=[],questions=[],writing=[],sources=[])
sections=[('roles',T('1. Люди и роли в предложении','1. Люди й ролі в реченні','1. People and sentence roles','1. Personer och satsdelar')),('ownership',T('2. Кому что принадлежит','2. Кому що належить','2. Who owns what','2. Vem äger vad')),('reference',T('3. Den, det, de и dem','3. Den, det, de та dem','3. Den, det, de and dem','3. Den, det, de och dem')),('reflexive',T('4. Свой и чужой · дополнительно SFI B','4. Своє й чуже · додатково SFI B','4. Reflexive ownership · SFI B extension','4. Reflexivt ägande · fördjupning sfi B')),('cheatsheet',T('5. Порядок слов и шпаргалка','5. Порядок слів і пам’ятка','5. Word order and quick reference','5. Ordföljd och lathund'))]
C['sections']=[dict(id=i,title=t,rules=[]) for i,t in sections]
def rule(sec,id,title,text,theory,pattern,examples,comparison,mistakes,limits,mini,sources=None,level='A'):
 r=dict(id=id,title=title,text=text,theory=theory,pattern=pattern,examples=examples,comparison=comparison,mistakes=mistakes,limits=limits,mini=mini,sources=sources or ['sag-pronouns'],level=level)
 next(s for s in C['sections'] if s['id']==sec)['rules'].append(r)
def mini(prompt,answer,explanation):return dict(prompt=prompt,answer=answer,explanation=explanation)
rule('roles','subjects',T('Кто? Формы подлежащего','Хто? Форми підмета','Who? Subject forms','Vem? Subjektsformer'),T('Jag — говорящий, du — собеседник. Han, hon, hen — человек, о котором говорят. Vi включает говорящего; ni — нескольких собеседников; de — тех, о ком говорят.','Jag — мовець, du — співрозмовник. Han, hon, hen — людина, про яку говорять. Vi включає мовця; ni — кількох співрозмовників; de — тих, про кого говорять.','Jag is the speaker; du is the listener. Han, hon and hen refer to a person being discussed. Vi includes the speaker; ni addresses several listeners; de refers to others.','Jag är den som talar och du den som lyssnar. Han, hon och hen syftar på en person man talar om. Vi omfattar talaren; ni tilltalar flera; de syftar på andra.'),T('Подлежащее — грамматическая опора предложения: о ком или о чём сообщают. В наших активных примерах это тот, кто действует. Den и det тоже могут быть подлежащими. Форма настоящего времени глагола одинакова: jag läser, ni läser.','Підмет — граматична основа: про кого чи про що повідомляють. У наших активних прикладах це той, хто діє. Den і det теж можуть бути підметами. Дієслово теперішнього часу однакове: jag läser, ni läser.','The subject is what the clause says something about. In these active examples it performs the action. Den and det can also be subjects. A present-tense verb keeps the same form with every person: jag läser, ni läser.','Subjektet är den eller det som satsen säger något om. I dessa aktiva exempel utför det handlingen. Även den och det kan vara subjekt. Presensformen är densamma för alla personer: jag läser, ni läser.'),T('подлежащее → глагол → …','підмет → дієслово → …','subject → verb → …','subjekt → verb → …'),[E('Jag arbetar på ett café.','Я работаю в кафе.','Я працюю в кафе.','I work in a café.'),E('Du läser och hon skriver.','Ты читаешь, а она пишет.','Ти читаєш, а вона пише.','You read and she writes.'),E('Vi väntar här. Ni kan gå in.','Мы ждём здесь. Вы можете войти.','Ми чекаємо тут. Ви можете зайти.','We are waiting here. You can go in.')],T('Hon läser — она читает. Henne обозначает объект и в этой позиции не подходит.','Hon läser — вона читає. Henne позначає об’єкт і тут не підходить.','Hon läser means she reads. Henne is an object form and cannot fill this subject slot.','Hon läser har hon som subjekt. Henne är objektsform och passar inte som subjekt här.'),T('Не пиши Mig arbetar. Нужно Jag arbetar. Местоимения пишутся со строчной буквы внутри предложения.','Не пиши Mig arbetar. Треба Jag arbetar. Усередині речення займенники пишемо з малої літери.','Avoid Mig arbetar; use Jag arbetar. Pronouns have lower case inside a sentence.','Skriv inte Mig arbetar utan Jag arbetar. Pronomen har liten bokstav inne i en mening.'),T('Ni одному человеку встречается, но не является обязательной вежливой формой. В этой главе ni — обращение к нескольким. Подлежащее не всегда деятель: в пассиве оно может получать действие.','Ni до однієї людини трапляється, але не є обов’язковою ввічливою формою. Тут ni — звертання до кількох. Підмет не завжди діяч: у пасиві він може зазнавати дії.','Ni to one person occurs but is not a required polite form. Here ni addresses several people. Subjects are not always agents: passive subjects can receive an action.','Ni till en person förekommer men krävs inte som artighetsform. Här används ni till flera. Subjekt är inte alltid den som handlar: i passiv kan subjektet utsättas för handlingen.'),mini(T('Замени Sara: Sara sjunger.','Заміни Sara: Sara sjunger.','Replace Sara: Sara sjunger.','Ersätt Sara: Sara sjunger.'),'Hon sjunger.',T('Hon заменяет Sara как подлежащее.','Hon замінює Sara як підмет.','Hon replaces Sara as subject.','Hon ersätter Sara som subjekt.')),['sag-pronouns','isof-du'])
rule('roles','objects',T('Кого? Кому? Объектные формы','Кого? Кому? Об’єктні форми','Object forms','Objektsformer'),T('Выбирай форму по роли в шведском предложении, а не по русскому падежному вопросу. После hjälper человеку соответствует объектная форма.','Обирай форму за роллю у шведському реченні, а не лише за українським відмінковим питанням. Після hjälper потрібна об’єктна форма.' ,'Choose the Swedish sentence role rather than translating a case question from another language. A person after hjälper takes an object form.','Välj form efter rollen i den svenska satsen. Efter hjälper står personen i objektsform.'),T('Jag→mig, du→dig, han→honom, hon→henne, hen→hen, vi→oss, ni→er, de→dem. Den и det не меняются. Объектные формы нужны и после предлогов: till mig, med henne.','Jag→mig, du→dig, han→honom, hon→henne, hen→hen, vi→oss, ni→er, de→dem. Den і det не змінюються. Об’єктні форми потрібні й після прийменників: till mig, med henne.','Jag→mig, du→dig, han→honom, hon→henne, hen→hen, vi→oss, ni→er, de→dem. Den and det stay unchanged. Use object forms after prepositions too: till mig, med henne.','Jag→mig, du→dig, han→honom, hon→henne, hen→hen, vi→oss, ni→er, de→dem. Den och det ändras inte. Objektsform används också efter preposition: till mig, med henne.'),T('подлежащее → глагол → дополнение / предлог → объектная форма','підмет → дієслово → додаток / прийменник → об’єктна форма','subject → verb → object / preposition → object form','subjekt → verb → objekt / preposition → objektsform'),[E('Jag hjälper henne.','Я помогаю ей.','Я допомагаю їй.','I help her.'),E('Hon hjälper mig.','Она помогает мне.','Вона допомагає мені.','She helps me.'),E('Vi ser dem.','Мы видим их.','Ми бачимо їх.','We see them.')],T('В первом примере jag — деятель, henne — получатель помощи; во втором hon — деятель, mig — получатель. Vi — подлежащее, dem — те, кого видят.','У першому прикладі jag — діяч, henne — отримувач допомоги; у другому hon — діяч, mig — отримувач. Vi — підмет, dem — ті, кого бачать.','In the first example jag acts and henne receives help; in the second hon acts and mig receives help. Vi is the subject and dem identifies those seen.','I första exemplet handlar jag och henne får hjälp; i andra handlar hon och mig får hjälp. Vi är subjekt och dem anger vilka vi ser.'),T('Jag hjälper hon → Jag hjälper henne. Hennes означает «её» как принадлежность и не заменяет henne.','Jag hjälper hon → Jag hjälper henne. Hennes означає належність і не замінює henne.','Jag hjälper hon → Jag hjälper henne. Hennes shows ownership and cannot replace henne here.','Jag hjälper hon → Jag hjälper henne. Hennes uttrycker ägande och kan inte ersätta henne här.'),T('Схема относится к простому активному предложению. При перестановке слов роль сохраняется; более сложный порядок безударных объектов изучается позже. Mig/dig часто звучат как mej/dej.','Схема стосується простого активного речення. За перестановки слів роль зберігається; складніший порядок ненаголошених об’єктів вивчається пізніше. Mig/dig часто звучать як mej/dej.','This pattern covers simple active clauses. Moving a phrase does not change its role; unstressed object placement is studied later. Mig/dig often sound like mej/dej.','Mönstret gäller enkla aktiva satser. En flyttad fras behåller sin roll; placering av obetonade objekt studeras senare. Mig/dig uttalas ofta mej/dej.'),mini(T('После med: Du sitter med ___ (jag).','Після med: Du sitter med ___ (jag).','After med: Du sitter med ___ (jag).','Efter med: Du sitter med ___ (jag).'),'mig',T('Med — предлог, поэтому mig.','Med — прийменник, тому mig.','Med is a preposition, so use mig.','Med är en preposition, alltså mig.')))
rule('roles','hen',T('Hen: одна форма в двух ролях','Hen: одна форма у двох ролях','Hen: one form, two roles','Hen: samma form i två roller'),T('Hen позволяет говорить о человеке без указания пола или использовать выбранное человеком местоимение.','Hen дає змогу говорити про людину без зазначення статі або вживати обраний людиною займенник.','Hen can refer to someone without specifying gender, or be the pronoun that person uses.','Hen kan syfta på en person utan att ange kön eller vara personens eget pronomen.'),T('Рекомендуемая объектная форма тоже hen; принадлежность — hens. Это местоимение единственного числа, не замена всем формам de.','Рекомендована об’єктна форма теж hen; належність — hens. Це займенник однини, а не заміна всім формам de.','The recommended object form is hen too; the possessive is hens. It is singular, not a replacement for all uses of de.','Rekommenderad objektsform är också hen; genitiv är hens. Hen är singular, inte en ersättning för alla användningar av de.'),S('Hen läser. / Jag ser hen. / Hens bok.'),[E('Kim är ny här. Hen bor nära skolan.','Ким здесь недавно. Ким живёт рядом со школой.','Кім тут нещодавно. Кім живе біля школи.','Kim is new here. They live near the school.'),E('Jag möter hen vid bussen.','Я встречаю Ким у автобуса.','Я зустрічаю Кім біля автобуса.','I meet them by the bus.')],T('Hon→henne, но hen→hen. Английское единственное they в переводе не делает шведское hen множественным.','Hon→henne, але hen→hen. Англійське однинне they у перекладі не робить шведське hen множиною.','Hon changes to henne, but hen stays hen. Singular they in the English translation does not make Swedish hen plural.','Hon blir henne men hen förblir hen. Engelskans singulara they i översättningen gör inte hen till plural.'),T('Не образуй hens как объект: Jag möter hens неверно.','Не утворюй hens як об’єкт: Jag möter hens неправильно.','Do not use hens as an object: Jag möter hens is wrong.','Använd inte hens som objekt: Jag möter hens är fel.'),T('Henom встречается, но Isof рекомендует hen. Выбор han/hon/hen для конкретного человека нельзя угадать по имени или профессии.','Henom трапляється, але Isof рекомендує hen. Han/hon/hen для конкретної людини не можна вгадати за ім’ям чи професією.','Henom occurs, but Isof recommends hen. A person’s name or job does not determine which pronoun they use.','Henom förekommer men Isof rekommenderar hen. Namn eller yrke avgör inte vilket pronomen en person använder.'),mini(T('Kim использует hen. Jag ringer ___.','Кім вживає hen. Jag ringer ___.','Kim uses hen. Jag ringer ___.','Kim använder hen. Jag ringer ___.'),'hen',T('После ringer объектная форма hen.','Після ringer об’єктна форма hen.','The object form after ringer is hen.','Objektsformen efter ringer är hen.')),['isof-hen','academy-hen'])
rule('ownership','possessives',T('Два вопроса: чей и какой предмет?','Два питання: чий і який предмет?','Two decisions: owner and noun','Två val: ägare och substantiv'),T('Сначала определи владельца, затем род и число вещи. Это разные решения.','Спочатку визнач власника, потім рід і число речі. Це різні рішення.','First identify the owner, then the noun’s gender and number. These are separate decisions.','Bestäm först ägaren och sedan substantivets genus och antal. Det är två olika val.'),T('Min/din/vår/er и sin имеют en-, ett- и множественную форму. Hans/hennes/hens/deras не меняются. После притяжательного определения существительное обычно без определённого суффикса: min bok, а не min boken.','Min/din/vår/er і sin мають en-, ett- і множинну форму. Hans/hennes/hens/deras не змінюються. Після присвійного означення іменник зазвичай без означеного суфікса: min bok, а не min boken.','Min/din/vår/er and sin have en, ett and plural forms. Hans/hennes/hens/deras do not change. A noun after a possessive normally lacks the definite suffix: min bok, not min boken.','Min/din/vår/er och sin har en-, ett- och pluralformer. Hans/hennes/hens/deras ändras inte. Substantivet efter possessivt attribut saknar normalt bestämd ändelse: min bok, inte min boken.'),T('владелец → притяжательная форма + существительное без определённого суффикса','власник → присвійна форма + іменник без означеного суфікса','owner → possessive + noun without definite suffix','ägare → possessivform + substantiv utan bestämd ändelse'),[E('Det är vår lärare.','Это наш преподаватель.','Це наш викладач.','This is our teacher.'),E('Deras barn går i skolan.','Их ребёнок ходит в школу.','Їхня дитина ходить до школи.','Their child goes to school.')],T('Henne — человек как объект; hennes bok — вещь этого человека. Слово barn без контекста бывает единственным и множественным; здесь речь об одном ребёнке.','Henne — людина як об’єкт; hennes bok — річ цієї людини. Barn без контексту буває одниною й множиною; тут ідеться про одну дитину.','Henne is a person as object; hennes bok names that person’s possession. Barn can be singular or plural without context; this example means one child.','Henne är en person som objekt; hennes bok anger en ägodel. Barn kan vara singular eller plural utan sammanhang; här avses ett barn.'),T('Min en bok и min boken → min bok. Не выбирай mitt по полу владельца.','Min en bok і min boken → min bok. Не обирай mitt за статтю власника.','Min en bok and min boken → min bok. Do not select mitt by the owner’s gender.','Min en bok och min boken → min bok. Välj inte mitt efter ägarens kön.'),T('Это правило для определений перед существительным. Самостоятельные формы тоже возможны: Boken är min. Dess для den/det дано только в справочной таблице.','Це правило для означень перед іменником. Самостійні форми теж можливі: Boken är min. Dess для den/det подано лише в довідковій таблиці.','This rule describes possessives before a noun. Independent forms also occur: Boken är min. Dess for den/det is included only as a reference form.','Regeln gäller possessiva attribut framför substantiv. Självständiga former finns också: Boken är min. Dess för den/det finns bara som referens i tabellen.'),mini(T('Исправь: vår skolan.','Виправ: vår skolan.','Correct: vår skolan.','Rätta: vår skolan.'),'vår skola',T('После vår нет суффикса -n.','Після vår немає суфікса -n.','No definite suffix -n follows vår.','Ingen bestämd ändelse -n efter vår.')))
rule('ownership','min',S('Min · mitt · mina'),T('Все три формы означают «мой»: меняется вещь, а владелец — всё тот же jag.','Усі три форми означають «мій»: змінюється річ, а власник — той самий jag.','All three mean my: the noun changes, while the owner remains jag.','Alla tre betyder att jag är ägare: substantivet ändras men ägaren är densamma.'),T('En-слово в единственном числе требует min, ett-слово — mitt, множественное число — mina независимо от рода. Учим существительное с артиклем, а не угадываем род по переводу.','En-слово в однині потребує min, ett-слово — mitt, множина — mina незалежно від роду. Вчимо іменник з артиклем, не вгадуємо рід за перекладом.','An en noun in singular takes min, an ett noun takes mitt, and plural takes mina regardless of gender. Learn the noun with its article rather than guessing from translation.','En-ord i singular får min, ett-ord får mitt och plural får mina oavsett genus. Lär dig substantiv med artikel i stället för att gissa från översättningen.'),T('en → min / ett → mitt / множественное → mina','en → min / ett → mitt / множина → mina','en → min / ett → mitt / plural → mina','en → min / ett → mitt / plural → mina'),[E('Min syster heter Vera.','Мою сестру зовут Вера.','Мою сестру звати Віра.','My sister is called Vera.'),E('Mitt rum är ljust.','Моя комната светлая.','Моя кімната світла.','My room is bright.'),E('Mina skor är torra.','Мои туфли сухие.','Мої туфлі сухі.','My shoes are dry.')],T('Mig — «меня/мне» в объектной роли, min/mitt/mina — «мой» или связь с говорящим: min syster не означает владение человеком.','Mig — «мене/мені» в об’єктній ролі, min/mitt/mina — «мій» або зв’язок з мовцем: min syster не означає володіння людиною.','Mig is an object form; min/mitt/mina mark ownership or association. Min syster does not mean owning a person.','Mig är objektsform; min/mitt/mina anger ägande eller anknytning. Min syster betyder inte att man äger en person.'),T('Mitt bok → min bok, потому что en bok. Min skor → mina skor, потому что несколько.','Mitt bok → min bok, бо en bok. Min skor → mina skor, бо їх кілька.','Mitt bok → min bok because en bok. Min skor → mina skor because it is plural.','Mitt bok → min bok eftersom det heter en bok. Min skor → mina skor eftersom det är plural.'),T('Форма согласуется с грамматическим родом, который может не совпадать с родом русского/украинского перевода: ett rum — mitt rum.','Форма узгоджується з граматичним родом, який може не збігатися з родом українського/російського перекладу: ett rum — mitt rum.','Agreement uses Swedish grammatical gender, which need not match gender in a translation: ett rum — mitt rum.','Böjningen följer svenskt grammatiskt genus, som inte behöver motsvara genus i översättningen: ett rum — mitt rum.'),mini(T('Мои окна: ___ fönster (несколько).','Мої вікна: ___ fönster (кілька).','My windows: ___ fönster (several).','Mina fönster: ___ fönster (flera).'),'mina',T('Несколько окон → mina.','Кілька вікон → mina.','Several windows → mina.','Flera fönster → mina.')))
rule('ownership','din',S('Din · ditt · dina'),T('Din/ditt/dina относится к одному собеседнику: вещь твоя.','Din/ditt/dina стосується одного співрозмовника: річ твоя.','Din/ditt/dina refers to one listener: the thing is yours.','Din/ditt/dina gäller en person som tilltalas: saken är din.'),T('En → din, ett → ditt, несколько → dina. Количество владельцев не меняется от dina: один человек может иметь много вещей.','En → din, ett → ditt, кілька → dina. Кількість власників не змінюється від dina: одна людина може мати багато речей.','En → din, ett → ditt, plural → dina. Dina does not mean several owners: one listener can own many things.','En → din, ett → ditt, plural → dina. Dina betyder inte flera ägare: en person kan ha många saker.'),T('du → din + en-слово / ditt + ett-слово / dina + множественное','du → din + en-слово / ditt + ett-слово / dina + множина','du → din + en noun / ditt + ett noun / dina + plural','du → din + en-ord / ditt + ett-ord / dina + plural'),[E('Var är din jacka?','Где твоя куртка?','Де твоя куртка?','Where is your jacket?'),E('Ditt namn står på listan.','Твоё имя есть в списке.','Твоє ім’я є у списку.','Your name is on the list.'),E('Dina böcker ligger här.','Твои книги лежат здесь.','Твої книжки лежать тут.','Your books are here.')],T('Dina böcker — книги одного собеседника; era böcker — книги нескольких собеседников в наших ситуациях.','Dina böcker — книжки одного співрозмовника; era böcker — книжки кількох співрозмовників у наших ситуаціях.','Dina böcker belongs to one listener; era böcker belongs to several listeners in these situations.','Dina böcker gäller en tilltalad person; era böcker gäller flera i våra situationer.'),T('Dig namn → ditt namn. Dig — объект «тебя/тебе», не принадлежность.','Dig namn → ditt namn. Dig — об’єкт «тебе/тобі», не належність.','Dig namn → ditt namn. Dig is an object form, not a possessive.','Dig namn → ditt namn. Dig är objektsform, inte possessivform.'),T('Эта таблица использует du одному. Особое обращение ni одному обсуждалось ранее; оно не требуется для вежливости.','Ця таблиця використовує du до одного. Особливе ni до одного розглядали раніше; воно не є вимогою ввічливості.','This table uses du for one listener. Special singular ni was discussed earlier and is not a politeness requirement.','Tabellen använder du till en person. Särskilt ni till en person har nämnts tidigare och krävs inte för artighet.'),mini(T('Твой яблочный сок: ___ äppeljuice (en).','Твій яблучний сік: ___ äppeljuice (en).','Your apple juice: ___ äppeljuice (en).','Din äppeljuice: ___ äppeljuice (en).'),'din',T('En äppeljuice → din.','En äppeljuice → din.','En äppeljuice takes din.','En äppeljuice får din.')))
rule('ownership','shared',S('Hans · hennes · deras; vår · er'),T('Hans, hennes и deras указывают на владельца, а не на род вещи. Vår и er изменяются по вещи.','Hans, hennes і deras указують на власника, а не на рід речі. Vår і er змінюються за річчю.','Hans, hennes and deras identify the owner, not the noun’s gender. Vår and er change with the noun.','Hans, hennes och deras anger ägaren, inte sakens genus. Vår och er böjs efter substantivet.'),T('Han→hans, hon→hennes, de→deras: одна и та же форма перед en, ett и множественным числом. Vi→vår/vårt/våra, ni→er/ert/era. Er может быть объектной формой или притяжательной: роль видна по окружению.','Han→hans, hon→hennes, de→deras: та сама форма перед en, ett і множиною. Vi→vår/vårt/våra, ni→er/ert/era. Er може бути об’єктною чи присвійною формою: роль видно з оточення.','Han→hans, hon→hennes, de→deras keep one form with en, ett and plural. Vi→vår/vårt/våra, ni→er/ert/era. Er can be an object or possessive; surrounding words reveal the role.','Han→hans, hon→hennes, de→deras har samma form med en, ett och plural. Vi→vår/vårt/våra, ni→er/ert/era. Er kan vara objekt eller possessivform; sammanhanget visar rollen.'),T('hans/hennes/deras + существительное / vår–vårt–våra / er–ert–era','hans/hennes/deras + іменник / vår–vårt–våra / er–ert–era','hans/hennes/deras + noun / vår–vårt–våra / er–ert–era','hans/hennes/deras + substantiv / vår–vårt–våra / er–ert–era'),[E('Hennes kök är stort.','Её кухня большая.','Її кухня велика.','Her kitchen is large.'),E('Vårt bord står vid fönstret.','Наш стол стоит у окна.','Наш стіл стоїть біля вікна.','Our table is by the window.'),E('Jag väntar på er vid er dörr.','Я жду вас у вашей двери.','Я чекаю на вас біля ваших дверей.','I am waiting for you at your door.')],T('Первое er после på обозначает людей, второе перед dörr — принадлежность. Их написание одинаково, функции различны.','Перше er після på позначає людей, друге перед dörr — належність. Написання однакове, функції різні.','The first er after på refers to people; the second before dörr marks ownership. Same spelling, different roles.','Första er efter på syftar på personer; andra er framför dörr anger ägande. Samma stavning, olika funktioner.'),T('Hennes не меняется по вещи: не добавляй окончание. Vår hus → vårt hus.','Hennes не змінюється за річчю: не додавай закінчення. Vår hus → vårt hus.','Do not add gender endings to hennes. Vår hus → vårt hus.','Lägg inte genusändelser till hennes. Vår hus → vårt hus.'),T('Для владельца, совпадающего с подлежащим третьего лица в простой части предложения, обычно нужны sin/sitt/sina — это следующий шаг.','Для власника, що збігається з підметом третьої особи у простій частині речення, зазвичай потрібні sin/sitt/sina — це наступний крок.','If a third-person owner is the subject of the same simple clause, sin/sitt/sina is normally needed; that is the next step.','Om ägaren är subjekt i tredje person i samma enkla sats behövs normalt sin/sitt/sina; det är nästa steg.'),mini(T('Наше письмо: ___ brev (ett).','Наш лист: ___ brev (ett).','Our letter: ___ brev (ett).','Vårt brev: ___ brev (ett).'),'vårt',T('Vi как владелец и ett brev → vårt.','Vi як власник і ett brev → vårt.','Owner vi plus ett brev → vårt.','Ägaren vi och ett brev → vårt.')))
rule('reference','den',T('Den · det · de: заменяем существительное','Den · det · de: замінюємо іменник','Den · det · de: replace a noun','Den · det · de: tillbaka till ett substantiv'),T('Местоимение может заменить уже названный предмет: учитывай шведский род и число, а не перевод.','Займенник може замінити вже названий предмет: зважай на шведський рід і число, а не переклад.','A pronoun can replace a previously named thing: use Swedish gender and number rather than the translation.','Ett pronomen kan ersätta en redan nämnd sak: följ svenskt genus och antal, inte översättningen.'),T('En-слово → den; ett-слово → det; несколько вещей → de как подлежащее, dem как объект. Den/det одинаковы в субъектной и объектной роли. Для людей обычно выбирают личное han/hon/hen или de.','En-слово → den; ett-слово → det; кілька речей → de як підмет, dem як об’єкт. Den/det однакові в обох ролях. Для людей зазвичай обирають han/hon/hen або de.','An en noun → den; an ett noun → det; plural things → de as subject and dem as object. Den/det have the same subject and object form. People normally take han/hon/hen or de.','En-ord → den; ett-ord → det; flera saker → de som subjekt och dem som objekt. Den/det har samma form som subjekt och objekt. För personer används normalt han/hon/hen eller de.'),S('en stol → den / ett äpple → det / två stolar → de–dem'),[E('Jag köper en lampa. Den är liten.','Я покупаю лампу. Она маленькая.','Я купую лампу. Вона маленька.','I buy a lamp. It is small.'),E('Vi har ett piano. Jag spelar på det.','У нас есть пианино. Я играю на нём.','У нас є піаніно. Я граю на ньому.','We have a piano. I play it.'),E('Här är skorna. De är nya. Jag provar dem.','Вот туфли. Они новые. Я их примеряю.','Ось туфлі. Вони нові. Я їх приміряю.','Here are the shoes. They are new. I try them on.')],T('Den в Den är liten заменяет en lampa. В den lilla lampan слово den стоит перед существительным как определённый артикль; это другая функция.','Den у Den är liten замінює en lampa. У den lilla lampan слово den стоїть перед іменником як означений артикль; це інша функція.','Den in Den är liten replaces en lampa. In den lilla lampan, den is a definite article before a noun; that is a different function.','Den i Den är liten ersätter en lampa. I den lilla lampan är den en bestämd artikel framför substantivet; det är en annan funktion.'),T('En lampa: не hon только потому, что «лампа» женского рода по-русски; шведское замещение — den.','En lampa: не hon лише тому, що «лампа» жіночого роду українською; шведська заміна — den.','Do not choose hon for a lamp based on gender in another language; Swedish uses den.','Välj inte hon för en lampa utifrån genus i ett annat språk; på svenska används den.'),T('Den/det могут также указывать на предмет в ситуации без названного существительного. Значение «этот/тот» требует контекста и ударения; не всякое den — замена en-слова.','Den/det можуть також указувати на предмет у ситуації без названого іменника. Значення «цей/той» залежить від контексту й наголосу; не кожне den замінює en-слово.','Den/det can also point to something in the situation without a named noun. Demonstrative meaning depends on context and stress; not every den substitutes an en noun.','Den/det kan också peka på något i situationen utan ett nämnt substantiv. Utpekande betydelse beror på sammanhang och betoning; varje den ersätter inte ett en-ord.'),mini(T('Ett kvitto лежит здесь. Замени существительное: ___ ligger här.','Ett kvitto лежить тут. Заміни іменник: ___ ligger här.','Ett kvitto is here. Replace the noun: ___ ligger här.','Ett kvitto ligger här. Ersätt substantivet: ___ ligger här.'),'Det',T('Ett kvitto → det.','Ett kvitto → det.','Ett kvitto takes det.','Ett kvitto ersätts med det.')))
rule('reference','det',T('Det är…: представить или описать','Det är…: представити чи описати','Det är…: introduce or describe','Det är…: presentera eller beskriva'),T('Det är… может целиком представлять человека, вещь или ситуацию: «это…». Здесь det не обязано заменять ett-слово.','Det är… може представляти людину, річ чи ситуацію: «це…». Тут det не мусить замінювати ett-слово.','Det är… can introduce a person, thing or situation. Here det does not have to replace an ett noun.','Det är… kan presentera en person, sak eller situation. Här behöver det inte ersätta ett ett-ord.'),T('Det är en stol называет то, что перед нами; stolen är gammal → den är gammal описывает уже известный стул. Det также служит формальным подлежащим при погоде и в det finns.','Det är en stol називає те, що перед нами; stolen är gammal → den är gammal описує вже відомий стілець. Det також є формальним підметом у погоді та det finns.','Det är en stol identifies what is in front of us; stolen är gammal → den är gammal describes a known chair. Det is also a formal subject for weather and in det finns.','Det är en stol identifierar det vi ser; stolen är gammal → den är gammal beskriver en känd stol. Det används också som formellt subjekt vid väder och i det finns.'),T('Det är + представление / det finns + что-либо / det + глагол погоды','Det är + представлення / det finns + щось / det + дієслово погоди','Det är + introduction / det finns + something / det + weather verb','Det är + presentation / det finns + något / det + väderverb'),[E('Vem är det? Det är min granne.','Кто это? Это мой сосед.','Хто це? Це мій сусід.','Who is it? It is my neighbour.'),E('Det finns en park här.','Здесь есть парк.','Тут є парк.','There is a park here.'),E('Det regnar i dag.','Сегодня идёт дождь.','Сьогодні йде дощ.','It is raining today.')],T('Это стул → Det är en stol. Этот стул красный → Den här stolen är röd. Det и den här не являются универсальными взаимозаменяемыми переводами «это».','Це стілець → Det är en stol. Цей стілець червоний → Den här stolen är röd. Det і den här не є універсально взаємозамінними перекладами.','This is a chair → Det är en stol. This chair is red → Den här stolen är röd. Det and den här are not interchangeable translations of this.','Det är en stol presenterar något. Den här stolen är röd beskriver den utpekade stolen. Det och den här kan inte alltid bytas mot varandra.'),T('Не заменяй det на den в Det är en lärare из-за en lärare. Не опускай det в Det regnar.','Не замінюй det на den у Det är en lärare через en lärare. Не пропускай det у Det regnar.','Do not replace det with den in Det är en lärare because lärare is en. Keep det in Det regnar.','Byt inte det mot den i Det är en lärare för att lärare är ett en-ord. Behåll det i Det regnar.'),T('Den är… тоже грамматично, когда den отсылает к известному en-слову. Выбор зависит от смысла и контекста; правило не запрещает den är вообще.','Den är… теж граматично, коли den відсилає до відомого en-слова. Вибір залежить від змісту; правило не забороняє den är загалом.','Den är… is grammatical when den refers to a known en noun. Meaning and context decide; this is not a ban on den är.','Den är… är grammatiskt när den syftar på ett känt en-ord. Betydelse och sammanhang avgör; den är är inte förbjudet.'),mini(T('О погоде: ___ snöar.','Про погоду: ___ snöar.','Weather: ___ snöar.','Väder: ___ snöar.'),'Det',T('Погодный глагол требует формального det.','Погодне дієслово потребує формального det.','The weather verb takes formal det.','Väderverbet får formellt det.')))
rule('reference','de-dem',T('De/dem на письме, dom в речи','De/dem на письмі, dom у мовленні','Written de/dem, spoken dom','De/dem i skrift, dom i tal'),T('De — подлежащее, dem — объект или форма после предлога. В обычной речи обе часто звучат dom.','De — підмет, dem — об’єкт або форма після прийменника. У звичайному мовленні обидві часто звучать dom.','De is the subject form; dem is the object form and follows prepositions. Both are commonly pronounced dom.','De är subjektsform; dem är objektsform och används efter preposition. Båda uttalas ofta dom.'),T('В нейтральном стандартном письме различай роли. Проверка заменой: vi→de, oss→dem. Deras отвечает на «чей?», а не «кого?».','У нейтральному стандартному письмі розрізняй ролі. Перевірка заміною: vi→de, oss→dem. Deras відповідає на «чий?», а не «кого?».','In neutral standard writing, keep the roles distinct. Try substitution: vi→de, oss→dem. Deras shows ownership rather than an object.','Skilj formerna i neutral standardskrift. Prova att byta: vi→de, oss→dem. Deras uttrycker ägande, inte objekt.'),T('de + глагол / глагол + dem / med–till–för + dem','de + дієслово / дієслово + dem / med–till–för + dem','de + verb / verb + dem / med–till–för + dem','de + verb / verb + dem / med–till–för + dem'),[E('De väntar på oss.','Они ждут нас.','Вони чекають на нас.','They are waiting for us.'),E('Vi går hem till dem.','Мы идём к ним домой.','Ми йдемо до них додому.','We are going to their home.')],T('De ser oss / vi ser dem. Разговорное dom помогает понять звук, но не отменяет разные письменные формы.','De ser oss / vi ser dem. Розмовне dom допомагає зрозуміти звук, але не скасовує різних письмових форм.','De ser oss / vi ser dem. Spoken dom helps with listening but does not remove the written distinction.','De ser oss / vi ser dem. Talets dom hjälper hörförståelsen men tar inte bort skillnaden i skrift.'),T('Dem kommer → De kommer. Jag talar med de → Jag talar med dem.','Dem kommer → De kommer. Jag talar med de → Jag talar med dem.','Dem kommer → De kommer. Jag talar med de → Jag talar med dem.','Dem kommer → De kommer. Jag talar med de → Jag talar med dem.'),T('Dom встречается и в неформальном письме. De как артикль перед прилагательным — другая функция: de nya skorna. Случаи de/dem som имеют дополнительные допустимые варианты и не используются здесь для однозначного теста.','Dom трапляється й у неформальному письмі. De як артикль перед прикметником — інша функція: de nya skorna. Випадки de/dem som мають додаткові допустимі варіанти й не використовуються тут для однозначного тесту.','Dom also occurs in informal writing. De as an article before an adjective is a different use: de nya skorna. De/dem som constructions allow additional variation and are excluded from single-answer tests here.','Dom förekommer också i informell skrift. De som artikel före adjektiv har en annan funktion: de nya skorna. Konstruktioner med de/dem som har fler möjliga former och används inte i entydiga test här.'),mini(T('После för: Jag lagar mat för ___. (de)','Після för: Jag lagar mat för ___. (de)','After för: Jag lagar mat för ___. (de)','Efter för: Jag lagar mat för ___. (de)'),'dem',T('Предлог för требует объектной формы dem.','Прийменник för потребує об’єктної форми dem.','The preposition för takes object dem.','Prepositionen för kräver objektsformen dem.')),['isof-de','sag-pronouns'])
rule('reflexive','sin',S('Sin · sitt · sina'),T('Если владелец — то же третье лицо, что и подлежащее в этой простой части предложения, используй sin/sitt/sina.','Якщо власник — та сама третя особа, що й підмет у цій простій частині речення, вживай sin/sitt/sina.','When the owner is the same third person as the subject of this simple clause, use sin/sitt/sina.','När ägaren är samma tredje person som subjektet i den enkla satsen används sin/sitt/sina.'),T('Сначала проверь связь с подлежащим, затем согласуй с вещью: sin bil (en), sitt hus (ett), sina nycklar (множественное). Подлежащее может быть han, hon, hen, de или имя. Для jag/du/vi/ni сохраняются min/din/vår/er.','Спочатку перевір зв’язок з підметом, потім узгодь з річчю: sin bil (en), sitt hus (ett), sina nycklar (множина). Підметом може бути han, hon, hen, de чи ім’я. Для jag/du/vi/ni зберігаються min/din/vår/er.','First check the link to the subject, then agree with the noun: sin bil (en), sitt hus (ett), sina nycklar (plural). The subject can be han, hon, hen, de or a name. Jag/du/vi/ni keep min/din/vår/er.','Kontrollera först syftningen till subjektet och böj sedan efter saken: sin bil (en), sitt hus (ett), sina nycklar (plural). Subjektet kan vara han, hon, hen, de eller ett namn. Jag/du/vi/ni behåller min/din/vår/er.'),T('подлежащее 3-го лица → глагол → sin/sitt/sina + своя вещь','підмет 3-ї особи → дієслово → sin/sitt/sina + своя річ','third-person subject → verb → sin/sitt/sina + its own thing','subjekt i tredje person → verb → sin/sitt/sina + egen sak'),[E('Han tvättar sin bil.','Он моет свою машину.','Він миє свою машину.','He washes his own car.'),E('Han tvättar hans bil.','Он моет его машину — машину другого мужчины.','Він миє його машину — машину іншого чоловіка.','He washes his car — another man’s car.'),E('De hämtar sina väskor.','Они забирают свои сумки.','Вони забирають свої сумки.','They collect their own bags.')],T('В первом примере владелец машины — подлежащее han. Во втором hans в обычном прочтении относится к другому мужчине; кто это, должен показать контекст.','У першому прикладі власник машини — підмет han. У другому hans у звичайному прочитанні стосується іншого чоловіка; хто це, має показати контекст.','In the first example the subject han owns the car. In the second hans normally refers to another man; context must identify him.','I första exemplet äger subjektet han bilen. I andra syftar hans normalt på en annan man; sammanhanget måste visa vem.'),T('Jag tar sin bok → Jag tar min bok. De tar deras bok не передаёт «свою» в нашем простом контексте: нужно sin bok.','Jag tar sin bok → Jag tar min bok. De tar deras bok не передає «свою» у нашому простому контексті: треба sin bok.','Jag tar sin bok → Jag tar min bok. For their own book in this simple context use De tar sin bok, not deras bok.','Jag tar sin bok → Jag tar min bok. För en egen bok i detta enkla sammanhang används De tar sin bok, inte deras bok.'),T('Sin не употребляется внутри подлежащего с отсылкой к этому же подлежащему: Hans syster kommer, не Sin syster kommer. Sin связано с третьим лицом, а не со шведским переводом любого русского «свой».','Sin не вживається всередині підмета з відсиланням до цього самого підмета: Hans syster kommer, не Sin syster kommer. Sin пов’язане з третьою особою, а не з перекладом будь-якого «свій».','Sin cannot refer back to a subject from inside that same subject: Hans syster kommer, not Sin syster kommer. It is third-person reflexive ownership, not a universal translation of own.','Sin kan inte syfta tillbaka på subjektet inifrån samma subjekt: Hans syster kommer, inte Sin syster kommer. Sin gäller reflexivt ägande i tredje person, inte alla betydelser av egen.'),mini(T('Eva берёт свой паспорт: Eva tar ___ pass (ett).','Eva бере свій паспорт: Eva tar ___ pass (ett).','Eva takes her own passport: Eva tar ___ pass (ett).','Eva tar sitt eget pass: Eva tar ___ pass (ett).'),'sitt',T('Владелец Eva совпадает с подлежащим; ett pass → sitt.','Власниця Eva збігається з підметом; ett pass → sitt.','Eva is the subject and owner; ett pass → sitt.','Eva är subjekt och ägare; ett pass → sitt.')),level='B')
rule('reflexive','clause',T('Граница части предложения · SFI B','Межа частини речення · SFI B','Clause boundaries · SFI B','Satsgränser · sfi B'),T('Каждая часть с личным глаголом имеет своё подлежащее. Начинай поиск владельца заново после границы части.','Кожна частина з особовим дієсловом має свій підмет. Починай пошук власника заново після межі частини.','Each finite clause has its own subject. Recheck the owner when entering a new clause.','Varje finit sats har sitt eget subjekt. Kontrollera ägaren på nytt när en ny sats börjar.'),T('В Eva säger att Leo tar sin cykel местоимение sin в придаточной части относится к Leo, а не автоматически к Eva. Если велосипед Евы, нужна hennes cykel. Подлежащее придаточного Leo отличается от Eva в главной части.','У Eva säger att Leo tar sin cykel займенник sin у підрядній частині стосується Leo, а не автоматично Eva. Якщо велосипед Єви, треба hennes cykel. Підмет підрядного Leo відрізняється від Eva в головній частині.','In Eva säger att Leo tar sin cykel, sin in the subordinate clause refers to Leo, not automatically Eva. For Eva’s bike use hennes cykel. Leo is the subordinate subject; Eva is the main-clause subject.','I Eva säger att Leo tar sin cykel syftar sin i bisatsen på Leo, inte automatiskt på Eva. För Evas cykel används hennes cykel. Leo är bisatsens subjekt och Eva huvudsatsens.'),S('Eva säger | att Leo tar sin cykel (Leo) / hennes cykel (Eva)'),[E('Eva säger att Leo tar sin cykel.','Ева говорит, что Лео берёт свой велосипед.','Єва каже, що Лео бере свій велосипед.','Eva says that Leo takes his own bike.'),E('Eva säger att Leo tar hennes cykel.','Ева говорит, что Лео берёт её велосипед.','Єва каже, що Лео бере її велосипед.','Eva says that Leo takes her bike.')],T('Изменилось одно слово, но владелец другой. Для ясности в сложном тексте можно повторить имя: Evas cykel.','Змінилося одне слово, але власник інший. Для ясності у складному тексті можна повторити ім’я: Evas cykel.','Changing one word changes the owner. Repeat a name for clarity in complex writing: Evas cykel.','Ett enda ord ändrar ägaren. Upprepa gärna namnet för tydlighet i komplicerad text: Evas cykel.'),T('Не связывай sin механически с первым человеком во всём предложении. Ищи подлежащее именно соответствующей части.','Не пов’язуй sin механічно з першою людиною в усьому реченні. Шукай підмет саме відповідної частини.','Do not mechanically connect sin to the first person in the whole sentence. Find the subject of the relevant clause.','Koppla inte sin mekaniskt till den första personen i hela meningen. Hitta subjektet i rätt sats.'),T('Это надёжная учебная модель для простых личных частей. В инфинитивных оборотах, косвенной речи и оборотах с подразумеваемым деятелем бывают более сложные связи. Они требуют отдельного разбора и не включены в однозначный зачёт.','Це надійна навчальна модель для простих особових частин. В інфінітивних зворотах, непрямій мові й зворотах із невираженим діячем бувають складніші зв’язки. Вони потребують окремого розбору й не входять до однозначного тесту.','This is a reliable learning model for simple finite clauses. Infinitives, reported viewpoints and constructions with an implicit agent can have more complex reference. Those need separate analysis and are excluded from single-answer assessment.','Detta är en användbar modell för enkla finita satser. Infinitivfraser, återgivna perspektiv och uttryck med underförstådd aktör kan ha mer komplicerad syftning. De kräver egen analys och ingår inte i det entydiga testet.'),mini(T('Nora vet att Ali läser sin bok. Чья книга в нашей модели?','Nora vet att Ali läser sin bok. Чия книжка в нашій моделі?','Nora vet att Ali läser sin bok. Whose book in this model?','Nora vet att Ali läser sin bok. Vems bok enligt modellen?'),'Alis bok',T('Подлежащее части att… — Ali.','Підмет частини att… — Ali.','Ali is the subject of the att clause.','Ali är subjekt i att-satsen.')),level='B')
rule('cheatsheet','order',T('Порядок слов: роль сохраняется','Порядок слів: роль зберігається','Word order keeps sentence roles','Ordföljd och satsdelar'),T('В простом сообщении начни с подлежащего, затем личный глагол и объект. В вопросе да/нет глагол выходит вперёд.','У простому повідомленні почни з підмета, далі особове дієслово й об’єкт. У питанні так/ні дієслово виходить уперед.','In a simple statement start with subject, finite verb and object. In a yes/no question the verb comes first.','I ett enkelt påstående kommer subjekt, finit verb och objekt. I en ja/nej-fråga står verbet först.'),T('В главной повествовательной части личный глагол стоит на второй позиции члена предложения. Если первым идёт I dag, затем глагол, потом подлежащее. Inte обычно после глагола, если подлежащее в начале.','У головній розповідній частині особове дієслово стоїть на другій позиції члена речення. Якщо спочатку I dag, далі дієслово, потім підмет. Inte зазвичай після дієслова, якщо підмет на початку.','In a declarative main clause the finite verb is in the second constituent position. If I dag comes first, the verb follows and the subject comes next. With an initial subject, inte normally follows the verb.','I en påstående huvudsats står det finita verbet på andra satsdelsplatsen. Om I dag står först följer verbet och sedan subjektet. Med subjekt först står inte normalt efter verbet.'),S('Jag ser henne. / Ser jag henne? / I dag ser jag henne.'),[E('Du känner honom.','Ты его знаешь.','Ти його знаєш.','You know him.'),E('Känner du honom?','Ты его знаешь?','Ти його знаєш?','Do you know him?'),E('I morgon möter vi er.','Завтра мы встречаем вас.','Завтра ми зустрічаємо вас.','Tomorrow we meet you.')],T('В Känner du honom? слово du осталось подлежащим, хотя оно после глагола. Позиция после глагола не всегда означает объект.','У Känner du honom? слово du лишилося підметом, хоча воно після дієслова. Позиція після дієслова не завжди означає об’єкт.','In Känner du honom?, du remains subject even after the verb. Following a verb does not automatically mean object.','I Känner du honom? är du fortfarande subjekt efter verbet. Placering efter verbet betyder inte automatiskt objekt.'),T('I morgon vi möter er → I morgon möter vi er. Не меняй vi на oss из-за его новой позиции.','I morgon vi möter er → I morgon möter vi er. Не змінюй vi на oss через його нову позицію.','I morgon vi möter er → I morgon möter vi er. Do not turn vi into oss because of its new position.','I morgon vi möter er → I morgon möter vi er. Byt inte vi mot oss på grund av den nya platsen.'),T('V2 считает члены предложения, а не отдельные слова: I morgon занимает одну позицию. Порядок слов в придаточных и перенос безударных объектов здесь не обобщаются.','V2 рахує члени речення, а не окремі слова: I morgon займає одну позицію. Порядок у підрядних і перенесення ненаголошених об’єктів тут не узагальнюємо.','V2 counts constituents, not individual words: I morgon occupies one position. Subordinate word order and unstressed object shift need separate rules.','V2 räknar satsdelar, inte enskilda ord: I morgon tar en plats. Bisatsordföljd och flyttning av obetonade objekt har egna regler.'),mini(T('Вопрос: Hjälper ___ mig? (du)','Питання: Hjälper ___ mig? (du)','Question: Hjälper ___ mig? (du)','Fråga: Hjälper ___ mig? (du)'),'du',T('Du — подлежащее вопроса, не объект.','Du — підмет питання, не об’єкт.','Du is the subject of the question.','Du är frågans subjekt.')),['sag-pronouns','sag-sentences'])
rule('cheatsheet','extras',T('Man · sig · själv — дополнительно SFI B','Man · sig · själv — додатково SFI B','Man · sig · själv — SFI B extension','Man · sig · själv — fördjupning sfi B'),T('Man — люди вообще; sig — действие возвращается к третьему лицу; själv — сам или без помощи.','Man — люди загалом; sig — дія повертається до третьої особи; själv — сам або без допомоги.','Man refers to people generally; sig marks a reflexive third-person object; själv means oneself or without help.','Man syftar allmänt på människor; sig är reflexivt objekt i tredje person; själv betyder egen person eller utan hjälp.'),T('Man не означает обязательно мужчину: здесь это обобщённое местоимение. В возвратной конструкции jag→mig, du→dig, vi→oss, ni→er, но han/hon/hen/de/man→sig. Själv усиливает: hon själv; форма множественного числа själva.','Man не обов’язково означає чоловіка: тут це узагальнений займенник. У зворотній конструкції jag→mig, du→dig, vi→oss, ni→er, але han/hon/hen/de/man→sig. Själv підсилює: hon själv; множина själva.','Man is a generic pronoun, not necessarily a man. Reflexive objects use jag→mig, du→dig, vi→oss, ni→er but han/hon/hen/de/man→sig. Själv adds emphasis; plural is själva.','Man är ett generiskt pronomen, inte nödvändigtvis en man. Reflexiva objekt är jag→mig, du→dig, vi→oss, ni→er men han/hon/hen/de/man→sig. Själv förstärker; pluralformen är själva.'),S('hon tvättar sig / jag tvättar mig / de gör det själva'),[E('Man kan låna böcker här.','Здесь можно брать книги.','Тут можна позичати книжки.','People can borrow books here.'),E('Hon tvättar sig och tar sin handduk.','Она моется и берёт своё полотенце.','Вона миється й бере свій рушник.','She washes herself and takes her towel.'),E('Vi lagar maten själva.','Мы готовим еду сами.','Ми готуємо їжу самі.','We cook the food ourselves.')],T('Sig — объект «себя», sin handduk — принадлежность. Själv не заменяет sig: Hon tvättar sig själv усиливает «саму себя».','Sig — об’єкт «себе», sin handduk — належність. Själv не замінює sig: Hon tvättar sig själv підсилює «саму себе».','Sig is a reflexive object; sin handduk marks ownership. Själv does not replace sig: Hon tvättar sig själv emphasizes herself.','Sig är reflexivt objekt; sin handduk anger ägande. Själv ersätter inte sig: Hon tvättar sig själv förstärker henne själv.'),T('Jag tvättar sig → Jag tvättar mig. Hon tar sig bok → Hon tar sin bok.','Jag tvättar sig → Jag tvättar mig. Hon tar sig bok → Hon tar sin bok.','Jag tvättar sig → Jag tvättar mig. Hon tar sig bok → Hon tar sin bok.','Jag tvättar sig → Jag tvättar mig. Hon tar sig bok → Hon tar sin bok.'),T('Возвратность зависит от глагола; не добавляй sig к каждому действию. Man имеет объектную форму en, но её активное употребление оставим на потом. Själv может означать и «в одиночку» по контексту.','Зворотність залежить від дієслова; не додавай sig до кожної дії. Man має об’єктну форму en, але її активне вживання залишимо на потім. Själv за контекстом може означати й «наодинці».','Reflexivity depends on the verb; do not add sig to every action. Man has object form en, left for later practice. Själv can also mean alone depending on context.','Reflexivitet beror på verbet; lägg inte sig till varje handling. Man har objektsformen en, som tränas senare. Själv kan också betyda ensam beroende på sammanhanget.'),mini(T('Они моются: De tvättar ___.','Вони миються: De tvättar ___.','They wash themselves: De tvättar ___.','De tvättar sig: De tvättar ___.'),'sig',T('De как подлежащее возвращает действие на себя → sig.','De як підмет повертає дію на себе → sig.','De receives its own action → sig.','Handlingen går tillbaka till de → sig.')),level='B')
def table(id,sec,title,headers,rows):C['tables'].append(dict(id=id,section=sec,title=title,headers=headers,rows=[dict(cells=[S(c) if isinstance(c,str) else c for c in r]) for r in rows]))
H=[T('Подлежащее','Підмет','Subject','Subjekt'),T('Дополнение','Додаток','Object','Objekt'),T('Значение','Значення','Meaning','Betydelse')]
