def join(a,b):return {k:a[k]+' '+b[k] for k in a}
def choice(prompt,opts,why,ref,final=False,context=None,category='forms',explanations=None):
 pool=C['finalTest']['questions'] if final else C['questions'];n=len(pool)+1
 q=dict(id=('pronouns-final-v1-q' if final else 'pronouns-practice-')+str(n).zfill(2),type='choice',prompt=prompt,options=[],answerId='o0',ruleRefs=ref.split(','),sources=['sag-pronouns'],category=category,difficulty=2 if final else 1)
 for i,s in enumerate(opts):q['options'].append(dict(id='o'+str(i),text=S(s),feedback=join((explanations[i] if explanations else R[s]),why)))
 # Stable rotation prevents a visible all-first answer pattern.
 shift=(n*3+1)%len(opts);q['options']=q['options'][shift:]+q['options'][:shift]
 if context:q['context']=context
 pool.append(q);return q

def cloze(prompt,answer,why,ref,type='cloze',tokens=None,context=None,accepted=None):
 q=dict(id='pronouns-practice-'+str(len(C['questions'])+1).zfill(2),type=type,prompt=prompt,answer=answer,good=why,bad=join(T('Сверь форму и роль.','Звір форму й роль.','Check the form and role.','Kontrollera form och roll.'),why),ruleRefs=ref.split(','))
 if tokens:q['tokens']=tokens
 if context:q['context']=context
 if accepted:q['accepted']=accepted
 C['questions'].append(q)
